const THEMES=['light','dark'],THN={ru:['Светлая тема','Тёмная тема'],uz:['Yorug‘ mavzu','Tungi mavzu'],en:['Light theme','Dark theme']};
const applyTheme=t=>{if(t!=='dark')t='light';document.documentElement.dataset.theme=t;document.body.classList.toggle('dark',t==='dark');const nl=(THN[typeof lang==='string'?lang:'ru']||THN.ru)[t==='dark'?0:1];document.querySelectorAll('.themes button').forEach(b=>{b.dataset.theme=t==='dark'?'light':'dark';b.setAttribute('aria-label',nl);b.title=nl});const m=document.querySelector('meta[name=theme-color]');if(m)m.content=t==='dark'?'#0f0f0f':'#ffffff'};
