const vid=u=>{try{const x=new URL(u);if(x.protocol!=='https:')return null;const h=x.hostname.replace(/^www\./,'');let id='';if(h==='youtu.be')id=x.pathname.slice(1);else if(h==='youtube.com'||h.endsWith('.youtube.com'))id=x.searchParams.get('v')||(x.pathname.match(/^\/(?:embed|shorts|live)\/([\w-]{11})/)||[])[1]||'';if(/^[\w-]{11}$/.test(id))return{t:'yt',id};if(/\.(mp4|webm|ogg)$/i.test(x.pathname))return{t:'file',u:x.href};return{t:'link',u:x.href}}catch(x){return null}};
const videoCard=(v,u)=>{const m=vid(v.url),pl=!m?'':m.t==='yt'?`<button type="button" class="vplayer" data-play="${m.id}" style="background-image:url('https://img.youtube.com/vi/${m.id}/hqdefault.jpg')" aria-label="${e(v.title)}"><span>${ic('play')}</span></button>`:m.t==='file'?`<video controls preload="metadata" src="${e(m.u)}"></video>`:`<a class="vplayer" href="${e(m.u)}" target="_blank" rel="noopener noreferrer" aria-label="${e(v.title)}"><span>${ic('play')}</span></a>`;return `<article class="video-card">${pl}<div class="video-info"><h3>${e(v.title)}</h3>${v.desc?`<p>${e(v.desc)}</p>`:''}${staff(u)?`<form data-a="delvideo" data-id="${v.id}"><button class="btn sm danger">${T('delete')}</button></form>`:''}</div></article>`};
const vidOk=u=>{try{return new URL(u).protocol==='https:'}catch(x){return false}};
const videoSection=(u,s)=>{const L=PX[lang],vs=D.videos.filter(v=>!s||(v.title+' '+v.desc).toLowerCase().includes(s)).sort((a,b)=>b.id-a.id);return (staff(u)?`<details class="panel collapsible"><summary>${ic('plus')}<span>${L.addvideo}</span>${ic('chev','chev')}</summary><form class="form-grid" data-a="addvideo">${fld(L.vtitle,`<input required name="title" maxlength="120">`)}${fld(L.vurl,`<input required name="url" type="url" placeholder="https://">`)}${fld(T('description'),`<input name="description" maxlength="300">`,'wide')}<div class="form-actions wide"><button class="btn primary">${T('save')}</button></div></form></details>`:'')+`<section class="video-grid">${vs.map(v=>videoCard(v,u)).join('')||`<div class="empty-state">${ic('video')}<p>${T('no_items')}</p></div>`}</section>`};
