const avatarImg=f=>new Promise(r=>{if(!f||!f.size)return r('');const i=new Image;i.onload=()=>{const c=document.createElement('canvas');c.width=c.height=160;const k=Math.max(160/i.width,160/i.height),w=i.width*k,h=i.height*k;c.getContext('2d').drawImage(i,(160-w)/2,(160-h)/2,w,h);r(c.toDataURL('image/jpeg',.8))};i.onerror=()=>r('');i.src=URL.createObjectURL(f)});
