const opts=(a,sel)=>a.map(([v,l])=>`<option value="${e(v)}" ${v==sel?'selected':''}>${e(l)}</option>`).join('');
const allCats=()=>[...CATS,...D.categories.map(c=>c.id)],catName=k=>CATS.includes(k)?T(k):(D.categories.find(c=>c.id===k)||{}).name||k;
const catOpts=s=>opts(allCats().map(c=>[c,catName(c)]),s);
const coverImg=f=>new Promise(r=>{if(!f||!f.size)return r('');const i=new Image,u=URL.createObjectURL(f);i.onload=()=>{const k=Math.min(1,480/Math.max(i.width,i.height)),c=document.createElement('canvas');c.width=i.width*k;c.height=i.height*k;c.getContext('2d').drawImage(i,0,0,c.width,c.height);c.toBlob(bl=>r(bl||''),'image/jpeg',.82)};i.onerror=()=>r('');i.src=u});
const bookData=async(f,old={})=>{const b={title:f.get('title').trim(),author:f.get('author').trim(),category:allCats().includes(f.get('category'))?f.get('category'):'fiction',inventory:f.get('inventory').trim(),isbn:f.get('isbn').trim(),copies:Math.max(1,+f.get('copies')||1),year:+f.get('year')||null,desc:f.get('description').trim(),cover:old.cover||''};if(!b.title||!b.author||!b.inventory)throw 0;if(D.books.some(x=>x.inventory===b.inventory&&x.id!==old.id))throw 0;const c=await coverImg(f.get('cover'));if(c)b.coverBlob=c;return b};
